// Verifies a call from CommerceOS (FX-55, ADR-110; n8n/deployment/import.md):
//   X-CommerceOS-Timestamp: unix seconds (at most 5 minutes old)
//   X-CommerceOS-Signature: v1=<hex HMAC-SHA256(COMMERCEOS_N8N_WEBHOOK_SECRET, "<timestamp>.<raw body>")>
// Needs COMMERCEOS_N8N_WEBHOOK_SECRET, N8N_BLOCK_ENV_ACCESS_IN_NODE=false and NODE_FUNCTION_ALLOW_BUILTIN=crypto in
// the n8n environment, and Raw Body on the trigger. The body used downstream is the one that was signed.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
let secret = $vars.COMMERCEOS_N8N_WEBHOOK_SECRET;
if (!secret) {
  try {
    secret = $env.COMMERCEOS_N8N_WEBHOOK_SECRET;
  } catch (e) {
    secret = undefined; // n8n Cloud refuses $env: use a Variable
  }
}
let reason = null;
let raw = null;
if (!secret) reason = 'n8n is not configured with COMMERCEOS_N8N_WEBHOOK_SECRET';
else if (!item.binary || !item.binary.data) reason = 'no raw body (enable Raw Body on the trigger)';
else raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const ts = String(headers['x-commerceos-timestamp'] || '');
const given = String(headers['x-commerceos-signature'] || '');
if (!reason && !/^\d{9,11}$/.test(ts)) reason = 'missing or malformed timestamp';
if (!reason && Math.abs(Date.now() / 1000 - Number(ts)) > 300) reason = 'timestamp too old or in the future';
if (!reason) {
  const expected = 'v1=' + crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
  const a = Buffer.from(given);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) reason = 'signature does not match';
}
let body = null;
if (!reason) {
  try {
    body = JSON.parse(raw);
  } catch (e) {
    reason = 'body is not JSON';
  }
}
return [{ json: { headers, body, signature_verified: !reason, signature_error: reason } }];

// 1. Authoritative Validation of Standard CommerceOS Event Envelope
const input = $input.first().json;
const body = input.body || input;
const event = body.event || body;

if (!event || typeof event !== 'object') {
  throw new Error('VALIDATION_ERROR: Missing event payload');
}

// Non-negotiable envelope attributes check
const requiredFields = ['id', 'type', 'version', 'tenant_id', 'aggregate_id', 'payload'];
for (const field of requiredFields) {
  if (!event[field]) {
    throw new Error(`VALIDATION_ERROR: Missing required event field '${field}'`);
  }
}

if (event.type !== 'order.created') {
  throw new Error(`VALIDATION_ERROR: Unsupported event type '${event.type}', expected 'order.created'`);
}

return [{
  json: {
    valid: true,
    event_id: event.id,
    event_type: event.type,
    event_version: event.version,
    tenant_id: event.tenant_id,
    aggregate_id: event.aggregate_id,
    actor_id: event.actor_id || 'system',
    correlation_id: event.correlation_id || event.aggregate_id,
    causation_id: event.id,
    timestamp: event.timestamp || new Date().toISOString(),
    payload: event.payload || {}
  }
}];

// 2. Prepare Context, Correlation, and Authoritative Idempotency Key
const validated = $input.first().json;

// Deterministic idempotency key per event and side-effecting task
const idempotencyKey = `n8n_ord_notif_${validated.event_id}`;

// Format recipient and message safely without exposing unneeded PII
const payload = validated.payload;
const recipientPhone = payload.customer_phone || payload.phone;
if (!recipientPhone) throw new Error('VALIDATION_ERROR: the order has no customer phone; nothing to send');
const grandTotal = payload.grand_total || 0;
const orderNumber = payload.order_number || validated.aggregate_id;

const notificationPayload = {
  template_code: 'ORDER_CONFIRMATION_SMS',
  channel: 'SMS',
  recipient: recipientPhone,
  customer_phone: recipientPhone,
  order_id: validated.aggregate_id,
  order_number: orderNumber,
  body: `Your order #${orderNumber} of BDT ${grandTotal} has been received and is being processed.`,
  metadata: {
    event_id: validated.event_id,
    tenant_id: validated.tenant_id,
    orchestrator: 'n8n'
  }
};

return [{
  json: {
    tenant_id: validated.tenant_id,
    correlation_id: validated.correlation_id,
    causation_id: validated.causation_id,
    idempotency_key: idempotencyKey,
    notification_payload: notificationPayload
  }
}];
